head.script:
scwin.onpageload = function() {
    progressbar1.set(10);
};
scwin.unitTest = function() {
    //init
    // WebSquare.wUnit.start();
    //Test step 1. 샘플실행(개발자도구) 후 요소검사(inspect)후 'mybar'로 검색 시 progressbar의 css 목록이 적용되었는지를 확인한다.참고사항) 브라우저에서 확인 할 경우에는 IE8이상에서 progressbar css 확인가능
    //1. After running the sample (developer tool), inspect the element and check that the list of css of progressbar is applied when searching with 'mybar'.Note) If you check in browser, you can check progress bar css in IE8 or later.
    //Verify step 1. class = 'w2progressbar w2progressbar_type4 mybar' is applied and shown.(Previously not applicable)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#progressbar1').hasClass('w2progressbar w2progressbar_type4 mybar')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 26-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
